/**
 * Initializes the zip file and extracts its contents.
 * @param jarFile The path to the jar file.
 * @return A sorted list of all zip entry names.
 * @throws IOException If an I/O error occurs while reading the file or zip entries.
 */
private List<String> init(String jarFile) throws IOException {
    List<String> content = new ArrayList<String>();
    ZipFile zf = null;
    try {
        zf = new ZipFile(jarFile);
        Enumeration<? extends ZipEntry> ze = zf.entries();
        while (ze.hasMoreElements()) {
            ZipEntry e = ze.nextElement();
            content.add(e.getName());
        }
    } finally {
        if (zf != null) {
            zf.close();
        }
    }
    Collections.sort(content);
    return content;
}

