```java
private String readFileFromJar(String fileName) throws IOException {
    JarFile jarFile = jarFile.new JarFile(jarFile.getJarEntry(fileName).getAbsolutePath());
    InputStream inputStream = jarFile.getInputStream(jarFile.getJarEntry(fileName));
    BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
    StringBuilder result = new StringBuilder();
    String str;
    while ((str = reader.readLine()) != null) {
        result.append(str);
        result.append(System.lineSeparator());
    }
    reader.close();
    inputStream.close();
    jarFile.close();
    return result.toString();
}
