/**
 * Rolls back an existing transaction.
 * @param tx The transaction object to be rolled back.
 * @throws IllegalStateException If no transaction is found for the given thread context.
 * @throws SecurityException If the current user is not authorized to perform the rollback operation.
 * @throws SystemException If a general system error occurs during the rollback process.
 * @throws BusinessTransactionException If there is a specific issue related to the business transaction during rollback.
 */
```java
public void rollback(Transaction tx) throws IllegalStateException, SecurityException, SystemException, BusinessTransactionException {
    synchronized (threadTx) {
        ThreadMXBean threadMxBean = ManagementFactory.getThreadMXBean();
        long[] threadIds = {threadTx.getId()};
        ThreadInfo[] threadInfos = threadMxBean.getThreadInfo(threadIds);

        if (tx == null) {
            String message = "Cannot get transaction for rollback";
            logger.severe(message);
            throw new IllegalStateException(message);
        }

        tx.rollback();
        threadTx.set(null);
    }
}
```

