private TreeNode<T> rotateRight(TreeNode<T> y) {
    /**
     * Performs a right rotation on the BST subtree rooted at node 'y'.
     * @param y The root of the subtree to be rotated.
     * @return The new root of the subtree after the right rotation.
     */

    TreeNode<T> x = y.getLeft();
    TreeNode<T> T2 = x.getRight();

    // Perform rotation
    x.setRight(y);
    y.setLeft(T2);

    // Update heights
    y.setHeight(1 + Math.max(getHeight(y.getLeft()), getHeight(y.getRight())));
    x.setHeight(1 + Math.max(getHeight(x.getLeft()), getHeight(x.getRight())));

    return x;
}

