    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String label = entry.getKey();
        V vertex = entry.getValue();

        // Add vertex to target graph
        target.addVertex(vertex);

        // Assuming there's a method to get edges associated with a vertex from the resultMap
        List<Edge<V, E>> relatedEdges = getRelatedEdgesFromResultMap(resultMap, vertex);

        for (Edge<V, E> edge : relatedEdges) {
            V connectedVertex = edge.getConnectedVertex(vertex);
            if (connectedVertex != null) {
                target.addEdge(vertex, connectedVertex, edge.getWeight());
            }
        }
    }
