/**
 * Initializes the given random number generator with a sequence of calls to nextDouble().
 * This helps in seeding the RNG properly.
 * @param rng The random number generator to be prepared.
 */
private static void prepareRNG(final Random rng) {
    for (int i = 0; i < 100; i++) {
        rng.nextDouble();
    }
}

private String encode(int[] path){
    /*
     * Encodes an array of atomic indices into a string representation using patterns 
     * and bond symbols.
     * 
     * @param path An array of integers representing atomic indices in a molecule.
     * @return A string that represents the encoded chemical path or structure.
     */
    StringBuilder sb = new StringBuilder(path.length * 3);
    for (int i = 0, n = path.length - 1; i <= n; i++) {
        IAtom atom = container.getAtom(path[i]);
        sb.append(toAtomPattern(atom));
        if (i < n) {
            IBond bond = container.getBond(container.getAtom(path[i]), container.getAtom(path[i + 1]));
            sb.append(getBondSymbol(bond));
        }
    }
    return sb.toString();
}

